  // ═════════ Cosmologie ═════════
  L('astro', 'cosmologie', {
    fr:[
      ['Qui a proposé le premier un Univers en expansion né d’un « atome primitif » ?', 'Georges Lemaître', [['Albert Einstein', 'Il a d’abord cru à un Univers statique. 🧊'], ['Isaac Newton', 'Bien trop tôt. 🍎'], ['Galilée', 'Bien trop tôt. 🔭']], 'Prêtre et physicien belge, il publie ses idées dès 1927 et 1931.'],
      ['Que vaut environ la constante de Hubble ?', 'environ 70 km/s par mégaparsec', [['300 000 km/s', 'C’est la vitesse de la lumière. ⚡'], ['9,81 m/s²', 'C’est la pesanteur terrestre. 🌍'], ['70 km/h', 'Non. 🚗']], 'Les mesures donnent entre 67 et 73 environ : c’est la « tension de Hubble ».'],
      ['Quels éléments se sont surtout formés lors de la nucléosynthèse primordiale ?', 'l’hydrogène et l’hélium (un peu de lithium)', [['le fer et le carbone', 'Ils viennent des étoiles. ⭐'], ['l’uranium', 'Il vient d’événements stellaires extrêmes. ☢️'], ['l’oxygène', 'Il vient des étoiles. 💨']], 'Elle s’est déroulée dans les toutes premières minutes après le Big Bang.'],
      ['Pourquoi le fond diffus cosmologique est-il aujourd’hui dans le domaine des micro-ondes ?', 'l’expansion a étiré sa longueur d’onde', [['il a toujours été en micro-ondes', 'Il était bien plus chaud au départ. 🔥'], ['les galaxies l’ont refroidi', 'Non. 🌌'], ['l’atmosphère le filtre', 'Non. ☁️']], 'Émis vers 3 000 K, il est aujourd’hui à environ 2,7 K.'],
      ['Quel satellite européen a cartographié le fond diffus avec une grande précision entre 2009 et 2013 ?', 'Planck', [['Hubble', 'Il observe surtout dans le visible. 🔭'], ['Gaia', 'Il cartographie les étoiles. ⭐'], ['Rosetta', 'Elle a étudié une comète. ☄️']], 'Ses mesures ont précisé l’âge et la composition de l’Univers.'],
      ['Qu’est-ce que l’inflation cosmique ?', 'une expansion extrêmement rapide de l’Univers dans ses tout premiers instants', [['la hausse des prix dans l’espace', 'Joli, mais non. 💸'], ['le gonflement d’une étoile en géante rouge', 'Non. 🔴'], ['l’expansion lente actuelle', 'Elle est bien plus ancienne et brutale. ⚡']], 'Elle expliquerait pourquoi l’Univers est si homogène à grande échelle.'],
      ['Quand a-t-on découvert que l’expansion de l’Univers accélère ?', 'en 1998, grâce à des supernovas lointaines', [['en 1929', 'C’est la découverte de l’expansion elle-même. 📈'], ['en 1965', 'C’est la découverte du fond diffus. 📡'], ['en 2015', 'C’est la détection des ondes gravitationnelles. 🌊']], 'Découverte récompensée par le prix Nobel de physique 2011.'],
      ['Qui a découvert par hasard le fond diffus cosmologique en 1965 ?', 'Arno Penzias et Robert Wilson', [['Edwin Hubble', 'Il a montré l’expansion. 📈'], ['Albert Einstein', 'Non. 🧠'], ['Galilée', 'Non. 🔭']], 'Ils pensaient d’abord à un parasite dans leur antenne radio.'],
      ['Le Big Bang est-il une explosion dans un espace déjà existant ?', 'non, c’est l’expansion de l’espace lui-même', [['oui, à partir d’un centre précis', 'Il n’y a pas de centre. 🎯'], ['oui, au centre de la Voie lactée', 'Non. 🌌'], ['oui, il y a 4,6 milliards d’années', 'C’est l’âge du Soleil. ☀️']], 'Toutes les régions de l’Univers s’éloignent les unes des autres.'],
      ['Que signifie un décalage vers le rouge z = 1 ?', 'les longueurs d’onde observées sont deux fois plus grandes qu’à l’émission', [['la source est à 1 année-lumière', 'Non. 📏'], ['la source se rapproche', 'Ce serait un décalage vers le bleu. 🔵'], ['la source est rouge à l’origine', 'Non. 🔴']], 'λobservée = (1 + z) × λémise.'],
      ['Quelle part de l’Univers représente l’énergie noire ?', 'environ 68 à 70 %', [['environ 5 %', 'C’est la matière ordinaire. 🔢'], ['environ 27 %', 'C’est la matière noire. 🌑'], ['100 %', 'Non. ⚖️']], 'Sa nature reste l’une des grandes énigmes de la physique.'],
      ['Qu’est-ce que l’horizon cosmologique ?', 'la limite au-delà de laquelle la lumière n’a pas eu le temps de nous parvenir', [['la ligne d’horizon sur Terre', 'Non. 🌅'], ['l’horizon d’un trou noir', 'C’est autre chose. 🕳️'], ['le bord de la Voie lactée', 'Non. 🌌']], 'Il délimite l’Univers observable.'],
      ['Comment appelle-t-on la période entre l’émission du fond diffus et l’allumage des premières étoiles ?', 'les âges sombres', [['l’âge d’or', 'Non. 🥇'], ['l’ère glaciaire', 'C’est l’histoire de la Terre. 🧊'], ['la Renaissance', 'C’est l’histoire humaine. 🎨']], 'Aucune étoile ne brillait encore : seul le gaz neutre remplissait l’Univers.'],
      ['Quelle observation d’Edwin Hubble, en 1929, a soutenu l’idée d’expansion ?', 'le décalage vers le rouge des galaxies augmente avec leur distance', [['Andromède se rapproche', 'C’est vrai, mais ça ne montre pas l’expansion. ↔️'], ['le Soleil tourne autour de la galaxie', 'Non. ☀️'], ['les orbites sont elliptiques', 'C’est Kepler. 📐']], 'Lemaître en avait tiré la même conclusion deux ans plus tôt.'],
      ['Dans quelle théorie physique s’inscrivent les modèles d’Univers en expansion ?', 'la relativité générale', [['la seule mécanique de Newton', 'Elle ne suffit pas. 🍎'], ['l’électrostatique', 'Non. ⚡'], ['la thermodynamique seule', 'Non. 🌡️']], 'Les équations de Friedmann décrivent l’évolution de l’Univers.']
    ],
    en:[
      ['Who first proposed an expanding Universe born from a “primeval atom”?', 'Georges Lemaitre', [['Albert Einstein', 'He first believed in a static Universe. 🧊'], ['Isaac Newton', 'Far too early. 🍎'], ['Galileo', 'Far too early. 🔭']], 'A Belgian priest and physicist, he published his ideas in 1927 and 1931.'],
      ['Roughly what is the Hubble constant?', 'about 70 km/s per megaparsec', [['300,000 km/s', 'That is the speed of light. ⚡'], ['9.81 m/s²', 'That is gravity on Earth. 🌍'], ['70 mph', 'No. 🚗']], 'Measurements give about 67 to 73: this is the “Hubble tension”.'],
      ['Which elements were mainly formed in primordial nucleosynthesis?', 'hydrogen and helium (a little lithium)', [['iron and carbon', 'They come from stars. ⭐'], ['uranium', 'It comes from extreme stellar events. ☢️'], ['oxygen', 'It comes from stars. 💨']], 'It took place in the first few minutes after the Big Bang.'],
      ['Why is the cosmic microwave background now in the microwave range?', 'expansion has stretched its wavelength', [['it was always microwaves', 'It was much hotter at first. 🔥'], ['galaxies cooled it down', 'No. 🌌'], ['the atmosphere filters it', 'No. ☁️']], 'Emitted at about 3,000 K, it is now about 2.7 K.'],
      ['Which European satellite mapped the cosmic background very precisely from 2009 to 2013?', 'Planck', [['Hubble', 'It mainly observes visible light. 🔭'], ['Gaia', 'It maps the stars. ⭐'], ['Rosetta', 'It studied a comet. ☄️']], 'Its results pinned down the age and make-up of the Universe.'],
      ['What is cosmic inflation?', 'an extremely fast expansion of the Universe in its very first instants', [['rising prices in space', 'Nice, but no. 💸'], ['a star swelling into a red giant', 'No. 🔴'], ['today’s slow expansion', 'It was far earlier and far more sudden. ⚡']], 'It would explain why the Universe is so uniform on large scales.'],
      ['When was it found that the expansion of the Universe is speeding up?', 'in 1998, using distant supernovae', [['in 1929', 'That is the discovery of expansion itself. 📈'], ['in 1965', 'That is the discovery of the cosmic background. 📡'], ['in 2015', 'That is the detection of gravitational waves. 🌊']], 'The discovery won the 2011 Nobel Prize in Physics.'],
      ['Who discovered the cosmic microwave background by chance in 1965?', 'Arno Penzias and Robert Wilson', [['Edwin Hubble', 'He showed expansion. 📈'], ['Albert Einstein', 'No. 🧠'], ['Galileo', 'No. 🔭']], 'At first they thought it was interference in their radio antenna.'],
      ['Is the Big Bang an explosion into space that already existed?', 'no, it is the expansion of space itself', [['yes, from a precise centre', 'There is no centre. 🎯'], ['yes, at the centre of the Milky Way', 'No. 🌌'], ['yes, 4.6 billion years ago', 'That is the age of the Sun. ☀️']], 'Every region of the Universe is moving away from every other.'],
      ['What does a redshift z = 1 mean?', 'the observed wavelengths are twice as long as when emitted', [['the source is 1 light year away', 'No. 📏'], ['the source is coming closer', 'That would be a blueshift. 🔵'], ['the source was red to begin with', 'No. 🔴']], 'λobserved = (1 + z) × λemitted.'],
      ['What share of the Universe is dark energy?', 'about 68 to 70%', [['about 5%', 'That is ordinary matter. 🔢'], ['about 27%', 'That is dark matter. 🌑'], ['100%', 'No. ⚖️']], 'Its nature remains one of the great puzzles of physics.'],
      ['What is the cosmological horizon?', 'the limit beyond which light has not had time to reach us', [['the skyline on Earth', 'No. 🌅'], ['a black hole’s horizon', 'That is something else. 🕳️'], ['the edge of the Milky Way', 'No. 🌌']], 'It marks the edge of the observable Universe.'],
      ['What is the period between the cosmic background and the first stars called?', 'the dark ages', [['the golden age', 'No. 🥇'], ['the ice age', 'That is Earth’s history. 🧊'], ['the Renaissance', 'That is human history. 🎨']], 'No star shone yet: only neutral gas filled the Universe.'],
      ['Which observation by Edwin Hubble in 1929 supported expansion?', 'the redshift of galaxies increases with their distance', [['Andromeda is coming closer', 'True, but that does not show expansion. ↔️'], ['the Sun orbits the galaxy', 'No. ☀️'], ['orbits are elliptical', 'That is Kepler. 📐']], 'Lemaitre had reached the same conclusion two years earlier.'],
      ['Which physical theory underlies models of an expanding Universe?', 'general relativity', [['Newton’s mechanics alone', 'Not enough. 🍎'], ['electrostatics', 'No. ⚡'], ['thermodynamics alone', 'No. 🌡️']], 'The Friedmann equations describe how the Universe evolves.']
    ],
    es:[
      ['¿Quién propuso primero un Universo en expansión nacido de un «átomo primitivo»?', 'Georges Lemaître', [['Albert Einstein', 'Al principio creyó en un Universo estático. 🧊'], ['Isaac Newton', 'Demasiado pronto. 🍎'], ['Galileo', 'Demasiado pronto. 🔭']], 'Sacerdote y físico belga, publicó sus ideas en 1927 y 1931.'],
      ['¿Cuánto vale más o menos la constante de Hubble?', 'unos 70 km/s por megapársec', [['300 000 km/s', 'Es la velocidad de la luz. ⚡'], ['9,81 m/s²', 'Es la gravedad terrestre. 🌍'], ['70 km/h', 'No. 🚗']], 'Las medidas dan entre 67 y 73 más o menos: es la «tensión de Hubble».'],
      ['¿Qué elementos se formaron sobre todo en la nucleosíntesis primordial?', 'el hidrógeno y el helio (algo de litio)', [['el hierro y el carbono', 'Vienen de las estrellas. ⭐'], ['el uranio', 'Viene de sucesos estelares extremos. ☢️'], ['el oxígeno', 'Viene de las estrellas. 💨']], 'Ocurrió en los primeros minutos después del Big Bang.'],
      ['¿Por qué el fondo cósmico de microondas está hoy en el rango de las microondas?', 'la expansión ha estirado su longitud de onda', [['siempre fue de microondas', 'Al principio era mucho más caliente. 🔥'], ['las galaxias lo enfriaron', 'No. 🌌'], ['la atmósfera lo filtra', 'No. ☁️']], 'Emitido a unos 3000 K, hoy está a unos 2,7 K.'],
      ['¿Qué satélite europeo cartografió el fondo cósmico con gran precisión entre 2009 y 2013?', 'Planck', [['Hubble', 'Observa sobre todo en el visible. 🔭'], ['Gaia', 'Cartografía las estrellas. ⭐'], ['Rosetta', 'Estudió un cometa. ☄️']], 'Sus medidas precisaron la edad y la composición del Universo.'],
      ['¿Qué es la inflación cósmica?', 'una expansión extremadamente rápida del Universo en sus primerísimos instantes', [['la subida de precios en el espacio', 'Bonito, pero no. 💸'], ['el hinchamiento de una estrella en gigante roja', 'No. 🔴'], ['la lenta expansión actual', 'Fue mucho antes y mucho más brusca. ⚡']], 'Explicaría por qué el Universo es tan homogéneo a gran escala.'],
      ['¿Cuándo se descubrió que la expansión del Universo se acelera?', 'en 1998, gracias a supernovas lejanas', [['en 1929', 'Es el descubrimiento de la propia expansión. 📈'], ['en 1965', 'Es el descubrimiento del fondo cósmico. 📡'], ['en 2015', 'Es la detección de las ondas gravitacionales. 🌊']], 'Descubrimiento premiado con el Nobel de Física de 2011.'],
      ['¿Quién descubrió por casualidad el fondo cósmico de microondas en 1965?', 'Arno Penzias y Robert Wilson', [['Edwin Hubble', 'Demostró la expansión. 📈'], ['Albert Einstein', 'No. 🧠'], ['Galileo', 'No. 🔭']], 'Al principio creyeron que era una interferencia en su antena de radio.'],
      ['¿Es el Big Bang una explosión en un espacio que ya existía?', 'no, es la expansión del propio espacio', [['sí, desde un centro concreto', 'No hay centro. 🎯'], ['sí, en el centro de la Vía Láctea', 'No. 🌌'], ['sí, hace 4600 millones de años', 'Es la edad del Sol. ☀️']], 'Todas las regiones del Universo se alejan unas de otras.'],
      ['¿Qué significa un corrimiento al rojo z = 1?', 'las longitudes de onda observadas son el doble que al emitirse', [['la fuente está a 1 año luz', 'No. 📏'], ['la fuente se acerca', 'Sería un corrimiento al azul. 🔵'], ['la fuente era roja al principio', 'No. 🔴']], 'λobservada = (1 + z) × λemitida.'],
      ['¿Qué parte del Universo representa la energía oscura?', 'alrededor del 68 al 70 %', [['alrededor del 5 %', 'Es la materia ordinaria. 🔢'], ['alrededor del 27 %', 'Es la materia oscura. 🌑'], ['el 100 %', 'No. ⚖️']], 'Su naturaleza sigue siendo uno de los grandes enigmas de la física.'],
      ['¿Qué es el horizonte cosmológico?', 'el límite más allá del cual la luz no ha tenido tiempo de llegarnos', [['la línea del horizonte en la Tierra', 'No. 🌅'], ['el horizonte de un agujero negro', 'Es otra cosa. 🕳️'], ['el borde de la Vía Láctea', 'No. 🌌']], 'Delimita el Universo observable.'],
      ['¿Cómo se llama el periodo entre el fondo cósmico y el encendido de las primeras estrellas?', 'la edad oscura', [['la edad de oro', 'No. 🥇'], ['la era glacial', 'Es historia de la Tierra. 🧊'], ['el Renacimiento', 'Es historia humana. 🎨']], 'Aún no brillaba ninguna estrella: solo gas neutro llenaba el Universo.'],
      ['¿Qué observación de Edwin Hubble, en 1929, apoyó la idea de expansión?', 'el corrimiento al rojo de las galaxias aumenta con su distancia', [['Andrómeda se acerca', 'Es cierto, pero no demuestra la expansión. ↔️'], ['el Sol gira alrededor de la galaxia', 'No. ☀️'], ['las órbitas son elípticas', 'Eso es Kepler. 📐']], 'Lemaître había llegado a la misma conclusión dos años antes.'],
      ['¿En qué teoría física se basan los modelos de Universo en expansión?', 'la relatividad general', [['solo la mecánica de Newton', 'No basta. 🍎'], ['la electrostática', 'No. ⚡'], ['solo la termodinámica', 'No. 🌡️']], 'Las ecuaciones de Friedmann describen la evolución del Universo.']
    ]
  });

